	}
	if r.Release == "" {
		logging.Log.Info("OS version is empty. Skip OVAL and gost detection")
		return false
	}
	if len(r.Packages)+len(r.SrcPackages) == 0 {
		logging.Log.Info("Number of packages is 0. Skip OVAL and gost detection")
		return false
	}
	if isTrivyResult(r) {
		logging.Log.Info("Scanned by Trivy. Skip OVAL and gost detection")
		return false
	}
	switch r.Family {
	case constant.FreeBSD, constant.Raspbian, constant.ServerTypePseudo:
		logging.Log.Infof("%s does not support package CVE detection with OVAL or gost. Skip detection", r.Family)
		return false
	}
	return true
}

// DetectGitHubCves fetches CVEs from GitHub Security Alerts
func DetectGitHubCves(r *models.ScanResult, githubConfs map[string]config.GitHubConf) error {
	if len(githubConfs) == 0 {
		return nil
	}
	for ownerRepo, setting := range githubConfs {
		ss := strings.Split(ownerRepo, "/")
		if len(ss) != 2 {
			return xerrors.Errorf("Failed to parse GitHub owner/repo: %s", ownerRepo)
		}
		owner, repo := ss[0], ss[1]
		n, err := DetectGitHubSecurityAlerts(r, owner, repo, setting.Token, setting.IgnoreGitHubDismissed)
		if err != nil {
			return xerrors.Errorf("Failed to access GitHub Security Alerts: %w", err)
		}
		logging.Log.Infof("%s: %d CVEs detected with GHSA %s/%s",
			r.FormatServerName(), n, owner, repo)
	}
	return nil
}

